def format_bytes(n):
    """Return a human-readable size such as '1.5 KB'."""
    if n < 1024:
        return f"{n} B"
    units = ["KB", "MB", "GB", "TB"]
    size = n
    unit_index = 0
    while size >= 1024 and unit_index < len(units):
        size /= 1024
        unit_index += 1
    if unit_index == 0:
        return f"{n} B"
    return f"{size:.1f} {units[unit_index - 1]}"
